'use strict';
(()=>{
 const PARTS=[['weapon','Skradziona broń'],['shield','Skradziona tarcza'],['helmet','Skradziony hełm']];
 const STATUSES=['dummies','recovery','ready','completed'];
 function quest(h){const q=h.gabrielQuest;if(!q)return null;if(!STATUSES.includes(q.status)||!Number.isInteger(q.dummies)||q.dummies<0||q.dummies>3||!Number.isInteger(q.recovered)||q.recovered<0||q.recovered>3||(q.status==='dummies'&&(q.dummies>=3||q.recovered!==0))||(q.status!=='dummies'&&q.dummies!==3)||(['ready','completed'].includes(q.status)&&q.recovered!==3)||(q.status==='recovery'&&q.recovered===3))throw Error('Nieprawidłowy postęp szkolenia Gabriela.');return q;}
 function unlocked(h){return quest(h)?.status==='completed';}
 function accept(h){if(quest(h))throw Error('Szkolenie zostało już rozpoczęte.');if(h.activeCombat||h.activeMission)throw Error('Najpierw zakończ obecną walkę lub misję.');return {...h,gabrielQuest:{status:'dummies',dummies:0,recovered:0}};}
 function enemy(h,stage,index){if(stage==='dummies')return {id:`gabriel-dummy-${index}`,name:`Manekin treningowy ${index+1}`,level:index+1,maxHp:60+index*30,stats:[3+index,2,1,4+index],attack:[2+index*2,4+index*2],atlas:'training',tile:0};const level=window.Progression.level(h);return {id:`gabriel-thief-${index}`,name:['Goblin zwiadowca','Goblin rabuś','Goblin szabrownik'][index],level,maxHp:Math.min(240,70+level*8)+index*10,stats:[Math.min(20,level+4),Math.min(20,level+3),2,Math.min(20,level+3)],attack:[Math.min(15,4+Math.floor(level/2)),Math.min(20,7+Math.floor(level/2))],tile:3};}
 function item(index){return {id:'gabriel-stolen-'+PARTS[index][0],name:PARTS[index][1],kind:'gabriel-armament',questPiece:PARTS[index][0],slot:'material',quantity:1};}
 function begin(h){const q=quest(h);if(!q||!['dummies','recovery'].includes(q.status))throw Error('Najpierw przyjmij lub zakończ etap szkolenia u Gabriela.');if(h.activeCombat||h.activeMission)throw Error('Najpierw zakończ obecną walkę lub misję.');if(q.status==='recovery'&&window.HeroSheet.bagItems(h).length>=25)throw Error('Zwolnij miejsce w plecaku na odzyskane uzbrojenie.');const index=q.status==='dummies'?q.dummies:q.recovered,player=window.BrandCombat.profile(h),power=Math.max(...player.stats)+player.level*2+(player.damageBonus||0);player.attack=[Math.max(1,power-3),power+3];return {...h,activeCombat:{id:crypto.randomUUID(),source:'gabriel',stage:q.status,questIndex:index,cost:0,sceneId:q.status==='dummies'?'training':'forest',reward:{gold:0,xp:0},battle:window.BrandCombat.createBattle(player,enemy(h,q.status,index),'hero'),nextHitAt:Date.now()+1100}};}
 function resolve(h,id){const q=quest(h),f=h.activeCombat,index=q?.status==='dummies'?q.dummies:q?.recovered;if(!q||!f||f.id!==id||f.source!=='gabriel'||!f.battle.winner||f.stage!==q.status||f.questIndex!==index||f.battle.enemy.id!==`gabriel-${q.status==='dummies'?'dummy':'thief'}-${index}`)throw Error('Walka trwa lub została już rozliczona.');const won=f.battle.winner==='hero';let next={...h,activeCombat:null,lastGabrielBattle:{id,won,stage:f.stage,index}};if(!won)return next;if(q.status==='dummies'){const dummies=q.dummies+1;return {...next,gabrielQuest:{...q,dummies,status:dummies===3?'recovery':'dummies'}};}if(window.HeroSheet.bagItems(h).length>=25)throw Error('Ekwipunek pełny. Zwolnij miejsce, a potem zgłoś wynik walki.');const prize=item(index),items=window.HeroSheet.inventory(h);if(items.some(i=>i.id===prize.id))throw Error('Ten element uzbrojenia został już odzyskany.');const recovered=q.recovered+1;return {...next,lootInventory:[...items,prize],gabrielQuest:{...q,recovered,status:recovered===3?'ready':'recovery'}};}
 function claim(h){const q=quest(h);if(q?.status!=='ready')throw Error('Najpierw pokonaj 3 manekiny i odzyskaj całe uzbrojenie.');if(h.activeCombat||h.activeMission)throw Error('Najpierw zakończ obecną walkę lub misję.');const items=window.HeroSheet.inventory(h),ids=PARTS.map((_,i)=>item(i).id);if(!ids.every(id=>items.some(i=>i.id===id&&i.kind==='gabriel-armament')))throw Error('Przynieś wszystkie trzy elementy skradzionego uzbrojenia.');const completed={...h,lootInventory:items.filter(i=>!ids.includes(i.id)),gabrielQuest:{...q,status:'completed'}};return window.PlayerStats?.recordMission(completed,'training')??completed;}
 function mount(root,state){root.innerHTML='<div class="gabriel-progress"></div><p class="gabriel-message" role="status"></p><div class="gabriel-combat" hidden></div>';const body=root.querySelector('.gabriel-progress'),message=root.querySelector('.gabriel-message');let disposed=false,busy=false;const combat=window.BrandCombat.mount(root.querySelector('.gabriel-combat'),{...state,onQuestResolved:next=>{render();message.textContent=next.lastGabrielBattle?.won?(next.lastGabrielBattle.stage==='dummies'?'Manekin pokonany.':'Odzyskane uzbrojenie trafiło do plecaka.'):'Porażka. Możesz spróbować ponownie.';}});
 function render(){if(disposed)return;try{const h=state.read(),q=quest(h),active=h.activeCombat?.source==='gabriel',other=!!h.activeMission||!!h.activeCombat&&!active;let action=!q?'accept':q.status==='completed'?'':q.status==='ready'?'claim':active?'resume':'fight';body.innerHTML='<h3>Próba Żelaznej Przysięgi</h3><p>Udowodnij, że jesteś gotów na wyprawy do lochów. Najpierw pokonaj trzy manekiny. Potem odbierz goblinom broń, tarczę i hełm skradzione ze zbrojowni.</p>'+`<ol class="gabriel-steps"><li>Manekiny: <strong>${q?.dummies||0} / 3</strong></li><li>Odzyskane uzbrojenie: <strong>${q?.recovered||0} / 3</strong></li><li>${q?.status==='completed'?'Uzbrojenie oddane — szkolenie ukończone':'Oddaj odzyskane uzbrojenie Gabrielowi'}</li></ol><p>Odzyskane przedmioty zajmują miejsca w plecaku do czasu oddania. Walki szkoleniowe nie kosztują energii. Nagroda: pozwolenie na wejście do lochów od poziomu 10.</p>${other?'<p>Najpierw zakończ obecną walkę lub misję.</p>':''}${q?.status==='completed'?'<p class="gabriel-complete">Gabriel zezwala Ci na wyprawy do lochów.</p>':''}<button type="button" class="primary" data-gabriel-action="${action}" ${!action||busy||other?'disabled':''}>${!q?'Rozpocznij szkolenie':q.status==='completed'?'Szkolenie ukończone':q.status==='ready'?'Oddaj uzbrojenie i ukończ szkolenie':active?'Wróć do walki':q.status==='dummies'?`Walcz z manekinem ${q.dummies+1} / 3`:`Odzyskaj: ${PARTS[q.recovered][1].toLowerCase()}`}</button>`;}catch(e){message.textContent=e.message;body.replaceChildren();}}
 async function click(e){const button=e.target.closest('[data-gabriel-action]');if(!button||busy||!button.dataset.gabrielAction)return;const action=button.dataset.gabrielAction;if(action==='resume'){await combat.open();return;}busy=true;render();try{const change=()=>{if(!disposed)state.update(h=>action==='accept'?accept(h):action==='claim'?claim(h):begin(h));};if(navigator.locks)await navigator.locks.request('pustkowie-hero-v2',change);else change();if(!disposed&&action==='fight')await combat.open();}catch(e){if(!disposed)message.textContent=e.name==='QuotaExceededError'?'Nie udało się zapisać szkolenia. Postęp pozostał bez zmian.':e.message;}finally{busy=false;render();}}
 function refresh(e){if(!busy&&(!e?.key||e.key==='pustkowie.hero.v2'))render();}root.addEventListener('click',click);window.addEventListener('storage',refresh);window.addEventListener('focus',refresh);render();return()=>{disposed=true;combat();root.removeEventListener('click',click);window.removeEventListener('storage',refresh);window.removeEventListener('focus',refresh);};}
 window.GabrielTraining={PARTS,quest,unlocked,accept,enemy,item,begin,resolve,claim,mount};
})();
